SELECT
    'SIAPE-FOLHA' SISTEMA,
    'ADAPI' ORGAO,
    FC.CPF_PESSOA CPF,
    FC.COD_INSTITUCIONAL MATRICULA,
    FC.NOME,
    FC.CARGO,
    FC.ESPECIALIDADE,
    FC.FUNCAO,
    FC.DATA_ADMISSAO,
    FC.COD_LOTACAO,
    FC.NOME_LOTACAO LOTACAO,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    FC.DATA_NASCIMENTO,
    TRUNC(MONTHS_BETWEEN(SYSDATE, TO_DATE(FC.DATA_NASCIMENTO)) / 12) IDADE,
    SX.NOME_SEXO SEXO,
    M.NOME_MUNICIPIO MUNICIPIO,
    CT.CODIGO COD_CATEGORIA_TRABALHADOR,
    CT.DESCRICAO CATEGORIA_TRABALHADOR,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    FC.REGIME,
    TF.NOME_TIPO_FUNCIONARIO TIPO_FUNCIONARIO,
    CASE
        WHEN IG.IND_ESOCIAL_REG_PREV = 'V1' THEN
            'Regime Geral da Previdência Social'
        WHEN IG.IND_ESOCIAL_REG_PREV = 'V2' THEN
            'Regime Próprio de Previdência Social'
        WHEN IG.IND_ESOCIAL_REG_PREV = 'V3' THEN
            'Regime de Previdência Social no Exterior'
    END REGIME_PREVIDENCIARIO,
    FS.DESCRICAO_FONTE,
    FO.CHAVE_FOLHA,
    FO.MES,
    FO.ANO,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO,
    FF.VALOR_CALCULADO VALOR,
    P.NOME_MAE,
    TT.DESCRICAO_TIPO TIPO_FOLHA,
    FC.NOME_EMPRESA_ORIGEM ORGAO_ORIGEM,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    E.EMAIL,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.COMPLEMENTO_ENDERECO,
    PEN.BAIRRO_ENDERECO,
    PEN.CIDADE_CIDADE,
    PEN.CEP
FROM
    SW_ADAPI.FOLHA FO
    JOIN SW_ADAPI.FOLHA_CONTRACHEQUE FC ON FC.ID_FOLHA = FO.ID_FOLHA
    JOIN SW_PUBLICO.PESSOA P ON P.ID_PESSOA = FC.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PE ON PE.ID_PESSOA = P.ID_PESSOA AND PE.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO SX ON SX.ID_SEXO = P.ID_SEXO
    LEFT JOIN SW_PUBLICO.RHB_CEP_MUNICIPIO_IBGE M ON M.ID_MUNICIPIO = FC.ID_MUNICIPIO
    LEFT JOIN SW_ADAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_ADAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.ESB_CATEGORIA_TRABALHADOR CT ON CT.ID_ESB_CATEG_TRABALHADOR = FP.ID_ESB_CATEG_TRABALHADOR
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO TF ON TF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_ADAPI.FUNCIONARIO_INF_GOVERNO IG ON IG.ID_FUNCIONARIO = FC.ID_FUNCIONARIO
    LEFT JOIN SW_ADAPI.FOLHA_FONTE_SEFAZ FS ON FS.ID_FONTE = FO.ID_FONTE
    JOIN SW_ADAPI.FOLHA_FICHA_FINANCEIRA FF ON FF.ID_FOLHA_FUNCIONARIO = FC.ID_FOLHA_FUNCIONARIO
    JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FF.ID_RUBRICA
    JOIN SW_PUBLICO.FOLHA_TAB_TIPO TT ON TT.ID_TIPO_FOLHA = FO.ID_TIPO_FOLHA
    JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = FC.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL E ON E.ID_PESSOA = FC.ID_PESSOA
WHERE
    FC.MES = 8
    AND FC.ANO = 2026
    AND FO.ID_TIPO_FOLHA = 1000000
    AND (R.TIPO IN ('R', 'D') OR R.COD_RUBRICA = 999997)
UNION ALL
SELECT
    'SIAPE-FOLHA' SISTEMA,
    'ADH' ORGAO,
    FC.CPF_PESSOA CPF,
    FC.COD_INSTITUCIONAL MATRICULA,
    FC.NOME,
    FC.CARGO,
    FC.ESPECIALIDADE,
    FC.FUNCAO,
    FC.DATA_ADMISSAO,
    FC.COD_LOTACAO,
    FC.NOME_LOTACAO LOTACAO,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    FC.DATA_NASCIMENTO,
    TRUNC(MONTHS_BETWEEN(SYSDATE, TO_DATE(FC.DATA_NASCIMENTO)) / 12) IDADE,
    SX.NOME_SEXO SEXO,
    M.NOME_MUNICIPIO MUNICIPIO,
    CT.CODIGO COD_CATEGORIA_TRABALHADOR,
    CT.DESCRICAO CATEGORIA_TRABALHADOR,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    FC.REGIME,
    TF.NOME_TIPO_FUNCIONARIO TIPO_FUNCIONARIO,
    CASE
        WHEN IG.IND_ESOCIAL_REG_PREV = 'V1' THEN
            'Regime Geral da Previdência Social'
        WHEN IG.IND_ESOCIAL_REG_PREV = 'V2' THEN
            'Regime Próprio de Previdência Social'
        WHEN IG.IND_ESOCIAL_REG_PREV = 'V3' THEN
            'Regime de Previdência Social no Exterior'
    END REGIME_PREVIDENCIARIO,
    FS.DESCRICAO_FONTE,
    FO.CHAVE_FOLHA,
    FO.MES,
    FO.ANO,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO,
    FF.VALOR_CALCULADO VALOR,
    P.NOME_MAE,
    TT.DESCRICAO_TIPO TIPO_FOLHA,
    FC.NOME_EMPRESA_ORIGEM ORGAO_ORIGEM,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    E.EMAIL,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.COMPLEMENTO_ENDERECO,
    PEN.BAIRRO_ENDERECO,
    PEN.CIDADE_CIDADE,
    PEN.CEP
FROM
    SW_ADH.FOLHA FO
    JOIN SW_ADH.FOLHA_CONTRACHEQUE FC ON FC.ID_FOLHA = FO.ID_FOLHA
    JOIN SW_PUBLICO.PESSOA P ON P.ID_PESSOA = FC.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PE ON PE.ID_PESSOA = P.ID_PESSOA AND PE.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO SX ON SX.ID_SEXO = P.ID_SEXO
    LEFT JOIN SW_PUBLICO.RHB_CEP_MUNICIPIO_IBGE M ON M.ID_MUNICIPIO = FC.ID_MUNICIPIO
    LEFT JOIN SW_ADH.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_ADH.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.ESB_CATEGORIA_TRABALHADOR CT ON CT.ID_ESB_CATEG_TRABALHADOR = FP.ID_ESB_CATEG_TRABALHADOR
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO TF ON TF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_ADH.FUNCIONARIO_INF_GOVERNO IG ON IG.ID_FUNCIONARIO = FC.ID_FUNCIONARIO
    LEFT JOIN SW_ADH.FOLHA_FONTE_SEFAZ FS ON FS.ID_FONTE = FO.ID_FONTE
    JOIN SW_ADH.FOLHA_FICHA_FINANCEIRA FF ON FF.ID_FOLHA_FUNCIONARIO = FC.ID_FOLHA_FUNCIONARIO
    JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FF.ID_RUBRICA
    JOIN SW_PUBLICO.FOLHA_TAB_TIPO TT ON TT.ID_TIPO_FOLHA = FO.ID_TIPO_FOLHA
    JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = FC.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL E ON E.ID_PESSOA = FC.ID_PESSOA
WHERE
    FC.MES = 8
    AND FC.ANO = 2026
    AND FO.ID_TIPO_FOLHA = 1000000
    AND (R.TIPO IN ('R', 'D') OR R.COD_RUBRICA = 999997)
UNION ALL
