    LEFT JOIN SW_PUBLICO.RHB_CEP_MUNICIPIO_IBGE M ON M.ID_MUNICIPIO = FC.ID_MUNICIPIO
    LEFT JOIN SW_SEPLAN.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FC.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEPLAN.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
